function longestBalancedSubsequence(s) {
  const invalidIndices = new Set();
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === "(") {
      stack.push(i);
    } else if (!stack.length) {
      invalidIndices.add(i);
    } else {
      stack.pop();
    }
  }

  while (stack.length) {
    invalidIndices.add(stack.pop());
  }

  const res = [];
  for (let i = 0; i < s.length; i++) {
    if (!invalidIndices.has(i)) {
      res.push(s[i]);
    }
  }
  return res.join("");
}

